-- SpigoleStay — SEED (dati di sviluppo, separati dallo schema).
-- ⚠️ STRUTTURE PLACEHOLDER — DA CONFERMARE con la mappa reale (5 strutture, gruppi, tipologie, ~12 unità).
-- Gli id sono letterali fissi per rendere leggibili i collegamenti tra tabelle.
-- Il seed gira come service role (bypassa la RLS).

-- ─────────── Tenant (Fase 1: uno solo) ───────────

-- Il profilo owner si collega dopo la registrazione reale su Supabase Auth:
--   update profiles set tenant_id = '10000000-...0001', role = 'owner' where id = auth.uid();

-- ─────────── Gruppi ───────────

-- ─────────── Strutture (5) — DA CONFERMARE ───────────

-- ─────────── Tipologie (si vendono) — DA CONFERMARE ───────────

-- ─────────── Unità (si assegnano, ~12) — nomi reali noti + placeholder ───────────

-- ─────────── Regola tassa di soggiorno (Comune di Siracusa) ───────────

-- ─────────── Ospiti ───────────

-- ─────────── Prenotazioni (agosto 2026) ───────────
  -- Prenotazione non ancora assegnata a un'unità (unit_id null): assegnabile fino al check-in.
  ('70000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000005', '40000000-0000-0000-0000-000000000006', null, '60000000-0000-0000-0000-000000000006', 'airbnb', 'confirmed', '2026-08-14', '2026-08-19', 2, 0);

-- ─────────── Folio di esempio (registro contabile) ───────────
-- Booking 1: 4 notti @ 95€ + pulizia + tassa soggiorno + commissione Booking + pagamento.

-- Booking 2 (Airbnb): 4 notti @ 110€ + pulizia + tassa + ritenuta 21% (acconto, non costo).

-- ─────────── Piani tariffari di default (uno per tipologia) ───────────

-- Striscia prezzi agosto 2026: base feriale, weekend +25% (placeholder).
select
  rp.tenant_id, rp.id, rp.room_type_id, d::date,
  case when extract(dow from d) in (5, 6) then 125 else 100 end,
  2
from rate_plans rp
cross join generate_series(date '2026-08-01', date '2026-08-31', interval '1 day') as d;
